    """Find the unique sensor row/column - a uniform row/col that appears only once"""
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    uniform_rows = {}
    uniform_cols = {}

    for r in range(rows):
        row = grid[r]
        val = row[0]
        if val > 0 and len(set(row)) == 1:
            uniform_rows.setdefault(val, []).append(r)

    for c in range(cols):
        col_values = [grid[r][c] for r in range(rows)]
        val = col_values[0]
        if val > 0 and len(set(col_values)) == 1:
            uniform_cols.setdefault(val, []).append(c)

    for val, r_indices in uniform_rows.items():
        if len(r_indices) == 1:
            return ('row', r_indices[0], val)

    for val, c_indices in uniform_cols.items():
        if len(c_indices) == 1:
            return ('col', c_indices[0], val)

    return None

